@Entity
@Table(name = "watch_progress", uniqueConstraints = @UniqueConstraint(columnNames = {"user_id", "drama_id"}))
@Getter
@Setter
@NoArgsConstructor
public class WatchProgress {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

